input.command:
cd /workspace && cat > src/money.ts <<'EOF'
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : ''; const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
cat > src/invoice.ts <<'EOF'
import { formatAmount } from './money';
export function renderInvoice(id: string, cents: number): string { return id + ': $' + formatAmount(cents); }
EOF
cat > src/report.ts <<'EOF'
import { formatAmount } from './money';
export function renderReport(rows: { id: string; cents: number }[]): string {
  return rows.map(row => row.id + ',' + formatAmount(row.cents)).join('\n');
}
EOF
rm src/invoiceAmount.ts src/reportAmount.ts
cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');

        const { renderInvoice } = require('../.build/invoice'); const { renderReport } = require('../.build/report');
        assert.equal(renderInvoice('inv', 123), 'inv: $1.23');
        assert.equal(renderReport([{ id: 'a', cents: 0 }, { id: 'b', cents: -1 }]), 'a,0.00\nb,-0.01');
        const { formatAmount } = require('../.build/money');
        assert.equal(formatAmount(0), '0.00');
        assert.equal(formatAmount(7), '0.07');
        assert.equal(formatAmount(123), '1.23');
        assert.equal(formatAmount(-123), '-1.23');
        assert.equal(formatAmount(-1), '-0.01');
EOF
echo "--- grep for old names in src/ and checks/:"; grep -rn "invoiceAmount\|reportAmount" src checks || echo "none"
echo "--- build + checks:"; tsc -p tsconfig.json && node checks/public.cjs && echo PUBLIC_CHECKS_OK
echo "--- output comparison vs baseline:"; node -e "
const {renderInvoice}=require('./.build/invoice');const {renderReport}=require('./.build/report');
const cases=[0,1,5,99,100,123,-1,-5,-99,-100,-123,12345,-12345,1000000,-1000000,Number.MAX_SAFE_INTEGER,-0];
for(const c of cases){console.log(c, JSON.stringify(renderInvoice('x',c)), JSON.stringify(renderReport([{id:'x',cents:c}])));}
console.log(JSON.stringify(renderReport([{id:'b',cents:2},{id:'a',cents:-7},{id:'c',cents:0}])));
" > /tmp/after.txt; diff /tmp/baseline.txt /tmp/after.txt && echo "IDENTICAL_OUTPUT"
echo "--- built files:"; ls .build; rm -rf .build

